const tabId = 2136412348;
const prods = await browserjs(tabId, () => {
  const seen = new Set();
  const results = [];
  const anchors = Array.from(document.querySelectorAll('a[href*="/product/prd-"]'));
  for (const a of anchors) {
    const href = a.href.split('?')[0];
    if (seen.has(href)) continue;
    seen.add(href);
    // find container
    let container = a.closest('div[class*="flex-col"]') || a.parentElement;
    for (let i = 0; i < 5; i++) {
      if (!container) break;
      if (container.innerText.includes('$')) break;
      container = container.parentElement;
    }
    const text = container ? container.innerText.replace(/\n+/g, ' | ') : a.innerText;
    results.push({ href: a.href, text });
  }
  return results.slice(0, 15);
});
console.log("Found products:", prods);

