const tabId = 2136412350;

// Helper to sleep
const sleep = ms => new Promise(r => setTimeout(r, ms));

const startX = 415;
const startY = 510;
const endX = 600;
const endY = 510;

console.log("Starting smooth drag from", startX, startY, "to", endX, endY);

// Move to start
await tool.cdp({ tabId, method: "Input.dispatchMouseEvent", params: { type: "mouseMoved", x: startX, y: startY } });
await sleep(100);

// Press
await tool.cdp({ tabId, method: "Input.dispatchMouseEvent", params: { type: "mousePressed", x: startX, y: startY, button: "left", clickCount: 1 } });
await sleep(100);

// Smooth move
const steps = 40;
for (let i = 1; i <= steps; i++) {
  const t = i / steps;
  // Ease in out
  const ease = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
  const currX = Math.round(startX + (endX - startX) * ease);
  const currY = Math.round(startY + Math.sin(t * Math.PI) * 4); // slight natural vertical wobble
  await tool.cdp({ tabId, method: "Input.dispatchMouseEvent", params: { type: "mouseMoved", x: currX, y: currY, button: "left" } });
  await sleep(25);
}

await sleep(150);
// Release
await tool.cdp({ tabId, method: "Input.dispatchMouseEvent", params: { type: "mouseReleased", x: endX, y: endY, button: "left", clickCount: 1 } });

await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });

const shot = await browser.screenshot({ tabId });
console.log("Shot after smooth drag:", shot.image);

