const tabId = 2136412352;
const prods = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/p/"]'));
  const seen = new Set();
  const results = [];
  for (const a of links) {
    const clean = a.href.split('?')[0].split('#')[0];
    if (seen.has(clean)) continue;
    seen.add(clean);
    let container = a.closest('div[class*="styles__StyledCol"]') || a.closest('div[class*="styles_"]') || a.parentElement;
    for (let i = 0; i < 4; i++) {
      if (!container) break;
      if (container.innerText && container.innerText.includes('$')) break;
      container = container.parentElement;
    }
    results.push({
      title: a.innerText.trim().replace(/\n+/g, ' | '),
      url: a.href,
      cardText: container ? container.innerText.replace(/\n+/g, ' | ') : ''
    });
  }
  return results.slice(0, 10);
});
console.log("Target product links:", JSON.stringify(prods, null, 2));

