const tabId = 2136412354;
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 6000 });

const recipeData = await browserjs(tabId, () => {
  const title = document.querySelector('h1')?.innerText;
  const rating = document.querySelector('.mm-recipes-review-bar, [data-rating], .review-star-text')?.innerText || document.body.innerText.match(/(\d\.\d)\s+stars/)?.[0];
  const ingredients = Array.from(document.querySelectorAll('.mm-recipes-structured-ingredients__list-item, li[class*="ingredient"], [data-ingredient-name]')).map(el => el.innerText.replace(/\s+/g, ' ').trim());
  const steps = Array.from(document.querySelectorAll('.mm-recipes-steps__list-item, ol li, [data-step-text]')).map(el => el.innerText.replace(/\s+/g, ' ').trim()).filter(s => s.length > 10);

  return {
    title,
    rating,
    ingredientsCount: ingredients.length,
    ingredients,
    stepsCount: steps.length,
    steps: steps.slice(0, 10),
    bodySnippet: document.body.innerText.slice(0, 1500)
  };
});
console.log("Recipe data:", JSON.stringify(recipeData, null, 2));

